namespace FrameScout {
 public static class PanelLayout {public static double[] Capture(Grid grid){return grid.ColumnDefinitions.Where((x,i)=>i%2==0).Select(x=>x.Width.Value).ToArray();}public static void Restore(Grid grid,double[] values){if(values==null||values.Length!=(grid.ColumnDefinitions.Count+1)/2)return;for(int i=0;i<values.Length;i++)if(!double.IsNaN(values[i])&&!double.IsInfinity(values[i]))grid.ColumnDefinitions[i*2].Width=new GridLength(Math.Max(0.1,Math.Min(10000,values[i])),GridUnitType.Star);}}
 public sealed class VideoValueComparer : IComparer {
  public static readonly string[] Keys={"Name","ModifiedTicks","Review","Status","DurationSeconds","ResolutionPixels","FrameCountValue"};readonly int key;readonly bool reverse;
  public VideoValueComparer(int key,bool reverse){this.key=key;this.reverse=reverse;}
  public int Compare(object x,object y){var a=(VideoItem)x;var b=(VideoItem)y;int c=0;switch(key){case 1:c=a.ModifiedTicks.CompareTo(b.ModifiedTicks);break;case 2:c=a.Review.CompareTo(b.Review);break;case 3:c=StringComparer.CurrentCulture.Compare(a.Status,b.Status);break;case 4:c=a.DurationSeconds.CompareTo(b.DurationSeconds);break;case 5:c=a.ResolutionPixels.CompareTo(b.ResolutionPixels);if(c==0)c=(a.Info==null?0:a.Info.Width).CompareTo(b.Info==null?0:b.Info.Width);if(c==0)c=(a.Info==null?0:a.Info.Height).CompareTo(b.Info==null?0:b.Info.Height);break;case 6:c=a.FrameCountValue.CompareTo(b.FrameCountValue);break;}if(c==0)c=NaturalVideoComparer.CompareNames(a.Name,b.Name);if(c==0)c=StringComparer.OrdinalIgnoreCase.Compare(a.Path,b.Path);return reverse?-c:c;}
 }
 public sealed partial class Shell {
  DockablePanel issueDock;
  void SetupWorkspace(){ScrollInteractions.Install();StableSplitter.Replace(Get<Grid>("VideoColumns"));Click("NavVideo",(s,e)=>Get<TabControl>("MainTabs").SelectedIndex=0);Click("NavSubtitles",(s,e)=>Get<TabControl>("MainTabs").SelectedIndex=1);Click("ResetStates",(s,e)=>ResetAllStates());Click("PreviousAnomalyVideo",(s,e)=>MoveAnomalyVideo(-1));Click("NextAnomalyVideo",(s,e)=>MoveAnomalyVideo(1));issueDock=new DockablePanel(Window,Get<FrameworkElement>("VideoIssuesPane"),Get<Button>("FloatIssues"),"异常列表",null,null);timer.Tick+=(s,e)=>Get<Button>("ResetStates").IsEnabled=scanCancel==null&&!refreshing&&!subtitlePanel.IsBusy;}
  VideoItem FindAnomalyVideo(int delta){var order=videos.Items.Cast<VideoItem>().ToList();int at=order.IndexOf(current);if(at<0){if(delta<0)return null;at=-1;}for(int i=at+delta;i>=0&&i<order.Count;i+=delta)if(order[i].Result!=null&&order[i].Result.Findings.Count>0)return order[i];return null;}
  void MoveAnomalyVideo(int delta){var item=FindAnomalyVideo(delta);if(item==null)return;videos.SelectedItem=item;videos.ScrollIntoView(item);}
  void UpdateAnomalyNavigation(){Get<Button>("PreviousAnomalyVideo").IsEnabled=FindAnomalyVideo(-1)!=null;Get<Button>("NextAnomalyVideo").IsEnabled=FindAnomalyVideo(1)!=null;}
  bool ResetAllStates(){if(scanCancel!=null||refreshing||subtitlePanel.IsBusy){statusText.Text="请先停止当前检测或校对，再重置状态。";return false;}resumeVideoAfterMove=false;Pause(false);forcedQueue=null;completed=total=active=0;percentages.Clear();foreach(var item in items){item.Result=null;item.ManualReview=null;item.Error=null;item.Running=false;item.Changed=true;item.Status="待检测";item.Refresh();}overall.Value=0;subtitlePanel.ResetInspection();issues.ItemsSource=null;RefreshResult();DrawMarkers();if(current!=null)Seek(0,true);ApplySort();UpdateReviewLabel();QueueSave();statusText.Text="已重置全部检测与审核状态；视频、字幕、剧本、名词表和关联已保留。";return true;}
 }
 public sealed partial class SubtitlePanel {
  DockablePanel subtitleFilesDock,subtitleIssuesDock,cuesDock;bool nounImporting,scriptLoading;
  void SetupSubtitleWorkspace(){StableSplitter.Replace(Get<Grid>("SubtitleColumns"));subtitleFilesDock=new DockablePanel(owner,Get<FrameworkElement>("SubtitleFilesPane"),Get<Button>("FloatSubtitleFiles"),"每集字幕",null,null,null,paths=>Import(paths));subtitleIssuesDock=new DockablePanel(owner,Get<FrameworkElement>("SubtitleIssuesPane"),Get<Button>("FloatSubtitleIssues"),"名词疑点",null,null);cuesDock=new DockablePanel(owner,Get<FrameworkElement>("SubtitleCuesPane"),Get<Button>("FloatCues"),"当前集 SRT",null,null);On("LoadScriptPath",(s,e)=>LoadTypedScript());Get<TextBox>("ScriptPathBox").PreviewKeyDown+=(s,e)=>{if(e.Key==Key.Enter){e.Handled=true;LoadTypedScript();}};Get<TextBox>("ScriptPathBox").PreviewDrop+=(s,e)=>{if(e.Data.GetDataPresent(DataFormats.FileDrop)){e.Handled=true;var paths=(string[])e.Data.GetData(DataFormats.FileDrop);if(paths.Length!=1){Status("请向剧本路径框拖入一个剧本文件。");return;}LoadScript(paths[0]);}};Get<TextBox>("ScriptPathBox").AddHandler(UIElement.PreviewDragOverEvent,new DragEventHandler((s,e)=>{e.Effects=e.Data.GetDataPresent(DataFormats.FileDrop)?DragDropEffects.Copy:DragDropEffects.None;e.Handled=true;}),true);On("ImportNouns",async(s,e)=>{var d=new Microsoft.Win32.OpenFileDialog{Title="导入名词表（可多选）",Filter="名词文本|*.txt;*.md;*.csv;*.tsv;*.json;*.docx;*.rtf|所有文件|*.*",Multiselect=true};if(d.ShowDialog(owner)==true)await ImportNounFiles(d.FileNames);});Get<Button>("ImportNouns").AllowDrop=true;Get<Button>("ImportNouns").PreviewDrop+=async(s,e)=>{if(e.Data.GetDataPresent(DataFormats.FileDrop)){e.Handled=true;await ImportNounFiles((string[])e.Data.GetData(DataFormats.FileDrop));}};}
  public string LayoutKey(){return string.Join(",",PanelLayout.Capture(Get<Grid>("SubtitleColumns")));}
  void LoadTypedScript(){string file=Get<TextBox>("ScriptPathBox").Text.Trim().Trim('"');if(file.Length==0){Status("请填写或选择剧本路径。");return;}LoadScript(Environment.ExpandEnvironmentVariables(file));}
  public void ResetInspection(){if(IsBusy)return;resumeSubtitleAfterMove=false;Pause();undo.Clear();undoGroup=null;foreach(var file in files){file.Completed=false;file.ManualReview=null;file.Issues.Clear();file.Status="待校对";foreach(var cue in file.Cues){cue.Corrected=null;cue.ReviewState=-1;cue.Refresh();}file.Refresh();}Select(current);if(current==null){Get<TextBlock>("CueOriginal").Text="原文：—";Get<TextBlock>("CueSuggestion").Text="建议：—";Get<TextBlock>("CueEvidence").Text="剧本出处：—";}logLines.Clear();Get<TextBox>("LogText").Clear();SetProgress(0,1,"尚未开始");Status("已重置字幕结果、审核与内存修改；素材、剧本、名词表、API 和视频关联已保留。");}
 }
}
